/**
 * Default S3 behavior only. Doing this here keeps distribution-wide
 * errorResponses off so API JSON 403/404 stay intact.
 */
function handler(event) {
  var request = event.request;
  var response = event.response;
  var uri = request.uri;
  var status = response.statusCode;

  if (uri === '/404.html') {
    // 304 has no body; rewriting its status alone yields a blank page.
    if (status === 304) {
      return htmlNotFoundResponse();
    }
    if (status === 200) {
      response.statusCode = 404;
      response.statusDescription = 'Not Found';
      // Disable caching so revalidation never returns a blank 304.
      response.headers['cache-control'] = { value: 'no-cache' };
      delete response.headers.etag;
      delete response.headers['last-modified'];
      return response;
    }
  }

  if (status === 404 || status === 403) {
    var ctHeader = response.headers['content-type'];
    var ct = ctHeader && ctHeader.value ? ctHeader.value.toLowerCase() : '';
    // S3 error documents are application/xml (sometimes empty content-type).
    if (
      ct.indexOf('xml') !== -1 ||
      ct === '' ||
      ct.indexOf('text/plain') !== -1
    ) {
      return htmlNotFoundResponse();
    }
  }

  return response;
}

function htmlNotFoundResponse() {
  return {
    statusCode: 404,
    statusDescription: 'Not Found',
    headers: {
      'content-type': { value: 'text/html; charset=utf-8' },
      'cache-control': { value: 'no-cache' },
    },
    body: unpackNotFoundHtml().replace(
      NOT_FOUND_YEAR,
      String(new Date().getUTCFullYear()),
    ),
  };
}

// `~a` stands for NOT_FOUND_DICT[0] and so on; an entry can use earlier keys.
function unpackNotFoundHtml() {
  var html = NOT_FOUND_HTML;
  for (var i = NOT_FOUND_DICT.length - 1; i >= 0; i--) {
    html = html
      .split('~' + String.fromCharCode(97 + i))
      .join(NOT_FOUND_DICT[i]);
  }
  return html;
}

